from __future__ import annotations

import base64
import io
import os
from typing import Any, Dict, List, Optional

import boto3


def _to_text(value: Any) -> Optional[str]:
    if value is None:
        return None
    if isinstance(value, str):
        return value.strip() or None
    if isinstance(value, (int, float, bool)):
        return str(value)
    if isinstance(value, dict):
        for key in ("Text", "Value", "text", "value", "Content", "content"):
            if key in value:
                txt = _to_text(value.get(key))
                if txt:
                    return txt
        if "Currency" in value and isinstance(value["Currency"], dict):
            cur = value["Currency"]
            amt = _to_text(cur.get("Amount"))
            code = _to_text(cur.get("Code"))
            if amt and code:
                return f"{amt} {code}"
            if amt:
                return amt
        return None
    return str(value).strip() or None


def _extract_line_item(item: Dict[str, Any]) -> Dict[str, Any]:
    result: Dict[str, Any] = {}
    if not isinstance(item, dict):
        return result

    for field_name, target in [
        ("Description", "description"),
        ("Name", "description"),
        ("Quantity", "quantity"),
        ("UnitPrice", "unit_price"),
        ("Price", "unit_price"),
        ("Amount", "amount"),
        ("TotalPrice", "amount"),
        ("Tax", "tax"),
    ]:
        if field_name in item and target not in result:
            result[target] = _to_text(item.get(field_name))

    # Preserve any useful nested values if available
    if "ProductCode" in item:
        result["product_code"] = _to_text(item.get("ProductCode"))
    if "Date" in item:
        result["date"] = _to_text(item.get("Date"))

    return {k: v for k, v in result.items() if v is not None}


def extract_receipt_fields(document_bytes: bytes, content_type: str = "application/pdf") -> Dict[str, Any]:
    """
    Extract merchant, tax, total, and items from a receipt using Amazon Textract AnalyzeExpense.

    Args:
        document_bytes: Receipt/document content as bytes.
        content_type: MIME type, e.g. 'application/pdf', 'image/jpeg', 'image/png'.

    Returns:
        Dict with keys: merchant, tax, total, items
    """
    client = boto3.client("textract")

    response = client.analyze_expense(
        Document={"Bytes": document_bytes},
    )

    summary_fields = response.get("ExpenseDocuments", [])
    merchant: Optional[str] = None
    tax: Optional[str] = None
    total: Optional[str] = None
    items: List[Dict[str, Any]] = []

    for expense_doc in summary_fields:
        summary = expense_doc.get("SummaryFields", []) or []
        for field in summary:
            ftype = _to_text(field.get("Type", {}).get("Text")) or _to_text(field.get("Type"))
            value = field.get("ValueDetection", {}).get("Text") or field.get("Value")
            if not value:
                value = _to_text(field.get("ValueDetection"))
            if not ftype or not value:
                continue

            ftype_norm = ftype.lower().replace("_", "")
            if merchant is None and ftype_norm in {
                "suppliername",
                "merchantname",
                "vendorname",
                "companyname",
                "businessname",
            }:
                merchant = _to_text(value)
            elif tax is None and ftype_norm in {
                "tax",
                "taxamount",
                "sales税",
                "vat",
                "gst",
                "hst",
                "pst",
            }:
                tax = _to_text(value)
            elif total is None and ftype_norm in {
                "total",
                "grandtotal",
                "amountdue",
                "totals",
                "totalamount",
            }:
                total = _to_text(value)

        line_item_groups = expense_doc.get("LineItemGroups", []) or []
        for group in line_item_groups:
            for line_item in group.get("LineItems", []) or []:
                parsed = {}
                for field in line_item.get("LineItemExpenseFields", []) or []:
                    key = _to_text(field.get("Type", {}).get("Text")) or _to_text(field.get("Type"))
                    val = _to_text(field.get("ValueDetection", {}).get("Text")) or _to_text(field.get("ValueDetection"))
                    if key and val:
                        parsed[key] = val
                items.append(_extract_line_item(parsed))

    return {
        "merchant": merchant,
        "tax": tax,
        "total": total,
        "items": items,
    }
